import{c as r,Z as n,Q as s,j as i,m as l,o as g}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"九歌·湘夫人","description":"","frontmatter":{"title":"九歌·湘夫人","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/2.md","filePath":"books/shici/chuci/2.md"}'),a={name:"books/shici/chuci/2.md"};function e(h,t,u,p,c,d){const o=n("PoemNav");return s(),i("div",null,[t[0]||(t[0]=l('<h1 id="九歌·湘夫人" tabindex="-1">九歌·湘夫人 <a class="header-anchor" href="#九歌·湘夫人" aria-label="Permalink to &quot;九歌·湘夫人&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>帝子降兮北渚，目眇眇兮愁予。 袅袅兮秋风，洞庭波兮木叶下。 登白薠兮骋望，与佳期兮夕张。 鸟何萃兮蘋中，罾何为兮木上？</p><p>沅有芷兮澧有兰，思公子兮未敢言。 荒忽兮远望，观流水兮潺湲。 麋何食兮庭中？蛟何为兮水裔？ 朝驰余马兮江皋，夕济兮西澨。 闻佳人兮召予，将腾驾兮偕逝。</p><p>筑室兮水中，葺之兮荷盖。 荪壁兮紫坛，播芳椒兮成堂。 桂栋兮兰橑，辛夷楣兮药房。 罔薜荔兮为帷，擗蕙櫋兮既张。 白玉兮为镇，疏石兰兮为芳。 芷葺兮荷屋，缭之兮杜衡。</p><p>合百草兮实庭，建芳馨兮庑门。 九嶷缤兮并迎，灵之来兮如云。 捐余袂兮江中，遗余褋兮澧浦。 搴汀洲兮杜若，将以遗兮远者。 时不可兮骤得，聊逍遥兮容与。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li><strong>帝子</strong>：指湘夫人。传说她是尧帝的女儿，故称帝子。</li><li><strong>降</strong>：降临。</li><li><strong>北渚</strong>：北岸的小洲。</li><li><strong>眇眇</strong>：远望的样子，目光悠远。</li><li><strong>愁予</strong>：使我忧愁。</li><li><strong>袅袅</strong>：微风吹拂的样子。</li><li><strong>洞庭</strong>：洞庭湖。</li><li><strong>波</strong>：起波浪。</li><li><strong>木叶</strong>：树叶。</li><li><strong>白薠</strong>：一种秋生的草，类似莎草。</li><li><strong>骋望</strong>：纵目远望。</li><li><strong>佳期</strong>：约会的好时光。</li><li><strong>夕张</strong>：在傍晚张设帷帐，准备迎接。</li><li><strong>萃</strong>：聚集。</li><li><strong>蘋</strong>：一种水草，也叫田字草。</li><li><strong>罾</strong>：一种用木棍或竹竿做支架的方形渔网。</li><li><strong>沅</strong>：沅水，在湖南西部。</li><li><strong>澧</strong>：澧水，在湖南西北部，流入洞庭湖。</li><li><strong>公子</strong>：指湘夫人。古代诸侯之女也可称公子。</li><li><strong>荒忽</strong>：恍惚，心神不定的样子。</li><li><strong>潺湲</strong>：水流缓慢的样子。</li><li><strong>麋</strong>：麋鹿。</li><li><strong>蛟</strong>：传说中的一种龙。</li><li><strong>水裔</strong>：水边。</li><li><strong>江皋</strong>：江边高地。</li><li><strong>济</strong>：渡水。</li><li><strong>西澨</strong>：西岸。澨，水边。</li><li><strong>腾驾</strong>：驾车飞奔。</li><li><strong>偕逝</strong>：一同前往。</li><li><strong>葺</strong>：覆盖屋顶。</li><li><strong>荷盖</strong>：用荷叶做屋顶。</li><li><strong>荪壁</strong>：用荪草装饰墙壁。荪，香草名。</li><li><strong>紫坛</strong>：用紫贝铺成的庭院地面。坛，庭院中的台地。</li><li><strong>播</strong>：散布。</li><li><strong>芳椒</strong>：芳香的花椒。</li><li><strong>桂栋</strong>：用桂木做屋梁。栋，正梁。</li><li><strong>兰橑</strong>：用木兰做屋椽。橑，屋椽。</li><li><strong>辛夷</strong>：香木名，即木兰。</li><li><strong>楣</strong>：门框上的横木。</li><li><strong>药房</strong>：用白芷装饰的房室。药，即白芷。</li><li><strong>罔</strong>：同&quot;网&quot;，编结。</li><li><strong>薜荔</strong>：一种蔓生香草。</li><li><strong>帷</strong>：帐幕。</li><li><strong>擗</strong>：剖开，分开。</li><li><strong>蕙櫋</strong>：用蕙草编织的帐顶。櫋，帐顶。</li><li><strong>张</strong>：张设。</li><li><strong>镇</strong>：压席的用具。</li><li><strong>疏</strong>：分布，陈列。</li><li><strong>石兰</strong>：香草名。</li><li><strong>芷葺</strong>：用白芷覆盖。</li><li><strong>缭</strong>：缠绕，这里指环绕。</li><li><strong>杜衡</strong>：香草名。</li><li><strong>实</strong>：充实，布满。</li><li><strong>芳馨</strong>：芳香。</li><li><strong>庑门</strong>：走廊和门。庑，堂周围的走廊。</li><li><strong>九嶷</strong>：九嶷山，传说中舜帝安葬的地方，在湖南省南部。</li><li><strong>缤</strong>：众多的样子。</li><li><strong>灵</strong>：神灵，指湘夫人的随从神灵。</li><li><strong>捐</strong>：抛弃，丢弃。</li><li><strong>袂</strong>：衣袖。</li><li><strong>褋</strong>：单衣。</li><li><strong>澧浦</strong>：澧水之滨。</li><li><strong>搴</strong>：拔取。</li><li><strong>汀洲</strong>：水中平地。</li><li><strong>杜若</strong>：香草名。</li><li><strong>遗</strong>：赠送。</li><li><strong>远者</strong>：远方的人，指湘夫人。</li><li><strong>骤得</strong>：屡次得到，轻易得到。</li><li><strong>逍遥</strong>：悠闲自在的样子。</li><li><strong>容与</strong>：从容自在的样子。</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>帝子湘夫人降临在北岸的小洲啊，我极目远望啊，心中充满忧愁。 秋风轻轻吹拂啊，洞庭湖泛起波浪啊，树叶纷纷飘落。 登上长满白薠的高地纵目远望啊，与佳人约好在傍晚张设帷帐迎接。 鸟儿为什么聚集在水草之中？渔网为什么挂在树木之上？</p><p>沅水有白芷啊澧水有兰草，思念湘夫人啊却不敢明言。 心神恍惚啊向远方眺望，只见流水啊缓缓流淌。 麋鹿为什么在庭院中觅食？蛟龙为什么在水边游动？ 清晨我驱马奔驰到江边高地，傍晚渡水到西岸。 听说佳人在召唤我啊，我将驾车飞奔与她同往。</p><p>在水中建造房屋啊，用荷叶覆盖屋顶。 用荪草装饰墙壁啊，紫贝铺成庭院，撒播芳香的花椒啊布满厅堂。 桂木做屋梁啊木兰做屋椽，辛夷木做门楣啊白芷装饰房室。 编结薜荔啊做成帐幕，剖开蕙草啊张设帐顶。 用白玉啊做成压席的镇石，分布石兰啊使其芳香。 用白芷覆盖啊荷叶做的屋顶，环绕着杜衡啊芬芳馥郁。</p><p>汇合百草啊布满庭院，建构芳香啊直到廊门。 九嶷山的神灵啊纷纷来迎，众神降临啊如同云聚。 把我衣袖啊抛入江中，把我单衣啊留在澧水之滨。 拔取汀洲上的杜若啊，准备送给啊远方的人。 美好的时光啊不可轻易得到，姑且逍遥自在啊从容徘徊。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《九歌·湘夫人》是屈原《九歌》组诗中的名篇，是祭祀湘水女神的乐歌。湘夫人是湘水女神，传说为尧帝之女、舜帝之妻娥皇、女英之一。全诗以湘君（湘水男神）的口吻，抒写对湘夫人的思念与追求，以及约会不遇的惆怅与失落。</p><p>诗开篇以&quot;袅袅兮秋风，洞庭波兮木叶下&quot;起兴，寥寥数笔便勾勒出一幅洞庭秋景图，秋风萧瑟、波涛涌动、落叶纷飞，渲染出凄清哀婉的氛围，成为千古传诵的写景名句。清人王夫之赞其为&quot;千古言秋之祖&quot;。</p><p>诗中通过&quot;鸟何萃兮蘋中，罾何为兮木上&quot;&quot;麋何食兮庭中？蛟何为兮水裔&quot;等反常景象的描写，以比兴手法暗示约会失期的失望与困惑。随后转入想象，诗人精心构筑了一座水中芳室，以荷、荪、桂、兰、辛夷、薜荔、蕙、石兰、杜若等香草美木装饰，象征着对美好爱情的向往与追求。</p><p>末段&quot;捐余袂兮江中，遗余褋兮澧浦&quot;，以抛衣江水的仪式表达思念与期盼，&quot;搴汀洲兮杜若，将以遗兮远者&quot;则表现了对爱情的执着与忠贞。全诗融写景、抒情、想象于一体，意境优美，情致缠绵，是《九歌》中最动人的篇章之一。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>屈原</strong>（约公元前340年－公元前278年），名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，被誉为“中华诗祖”。</p><p><a href="/authors/quyuan.html">查看作者详情 →</a></p></blockquote>',22)),g(o)])}const m=r(a,[["render",e]]);export{_ as __pageData,m as default};
